// generate_lived_world.js — Texture of daily life in Meridian 88, 2200
// 60 documents + 6 synthetics
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const DOC_DIR = path.join(__dirname, '..', 'engine', 'data', 'documents');
const SYNTH_DIR = path.join(__dirname, '..', 'engine', 'data', 'synthetics');

const existingDocs = new Set(fs.readdirSync(DOC_DIR).map(f => f.toLowerCase()));
const existingSynths = new Set(fs.readdirSync(SYNTH_DIR).map(f => f.toLowerCase()));

function genId() { return crypto.randomBytes(16).toString('hex'); }

function slugify(str) {
  return str.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 80);
}

let written = 0, skipped = 0;

function writeDoc(doc) {
  const id = genId();
  const filename = id + '.json';
  if (existingDocs.has(filename)) { console.log('SKIP (id collision): ' + filename); skipped++; return; }
  const lines = doc.body.split('\n');
  const headings = [];
  for (const line of lines) { const m = line.match(/^#{1,3}\s+(.+)/); if (m) headings.push(m[1]); }
  const entity = {
    id,
    file_name: slugify(doc.title),
    title: doc.title,
    category: doc.category,
    body: doc.body,
    line_count: lines.length,
    headings,
    tags: doc.tags
  };
  fs.writeFileSync(path.join(DOC_DIR, filename), JSON.stringify(entity, null, 2), 'utf8');
  existingDocs.add(filename);
  console.log('WROTE doc: ' + doc.title.slice(0, 60));
  written++;
}

function writeSynth(s) {
  const id = genId();
  const filename = id + '.json';
  if (existingSynths.has(filename)) { console.log('SKIP (id collision): ' + filename); skipped++; return; }
  const entity = {
    id,
    name: s.name.slice(0, 60),
    type: 'synthetic_life',
    aliases: s.aliases || [],
    classification: s.classification || 'Android (Synthetic Person)',
    disposition: s.disposition,
    habitat: s.habitat,
    origin: s.origin,
    status: 'active',
    description: s.description,
    observed_behavior: s.observed_behavior,
    encounter_frequency: s.encounter_frequency || 'rare',
    confirmed_sightings: s.confirmed_sightings || 0,
    location: s.location,
    dti_rating: s.dti_rating || 0.5,
    story_hooks: s.story_hooks || [],
    paratechnological: s.paratechnological || false,
    tags: s.tags
  };
  fs.writeFileSync(path.join(SYNTH_DIR, filename), JSON.stringify(entity, null, 2), 'utf8');
  existingSynths.add(filename);
  console.log('WROTE synth: ' + s.name);
  written++;
}

